        try:
            response = self.process_refresh_token_response(request, *args, **kwargs)
        except SocialAuthBaseException as error:
            error.stage = "refresh"
            raise
        except ValueError as json_error:
            raise AuthResponseError(
                self, code="malformed_response", stage="refresh"
